-- Authentication hardening schema (SQLite).
-- Password material must be an Argon2id encoded hash generated by trusted server code.
-- Never store plaintext passwords, reversible password encryption, or session bearer tokens.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS user_credentials (
    user_id TEXT NOT NULL PRIMARY KEY REFERENCES users(user_id) ON DELETE RESTRICT,
    password_hash TEXT NOT NULL,
    password_algorithm TEXT NOT NULL DEFAULT 'argon2id' CHECK (password_algorithm = 'argon2id'),
    password_changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    password_expires_at TEXT,
    failed_attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (failed_attempt_count >= 0),
    locked_until TEXT,
    credential_version INTEGER NOT NULL DEFAULT 1 CHECK (credential_version > 0),
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS user_sessions (
    session_id TEXT NOT NULL PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    company_id TEXT NOT NULL REFERENCES companies(company_id) ON DELETE RESTRICT,
    token_hash TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    revoked_at TEXT,
    revoke_reason TEXT,
    ip_address TEXT,
    user_agent TEXT,
    CHECK (length(token_hash) >= 64)
);
CREATE INDEX IF NOT EXISTS ix_user_sessions_active_user
    ON user_sessions(user_id, company_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS auth_events (
    auth_event_id INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id TEXT REFERENCES companies(company_id) ON DELETE RESTRICT,
    user_id TEXT REFERENCES users(user_id) ON DELETE RESTRICT,
    username_attempt TEXT NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN
        ('login_succeeded','login_failed','account_locked','logout','session_revoked','password_changed','password_reset')),
    occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    correlation_id TEXT,
    ip_address TEXT,
    user_agent TEXT,
    details TEXT
);
CREATE INDEX IF NOT EXISTS ix_auth_events_company_time
    ON auth_events(company_id, occurred_at);
CREATE INDEX IF NOT EXISTS ix_auth_events_user_time
    ON auth_events(user_id, occurred_at);

-- Enforce that a session's company matches its user's owning company.
CREATE TRIGGER IF NOT EXISTS trg_user_sessions_company_insert
BEFORE INSERT ON user_sessions
WHEN NOT EXISTS (
    SELECT 1 FROM users u
    WHERE u.user_id = NEW.user_id AND u.company_id = NEW.company_id
      AND u.is_active = 1 AND u.is_deleted = 0
)
BEGIN
    SELECT RAISE(ABORT, 'auth_session_company_mismatch_or_inactive_user');
END;

CREATE TRIGGER IF NOT EXISTS trg_user_sessions_company_update
BEFORE UPDATE OF user_id, company_id ON user_sessions
WHEN NOT EXISTS (
    SELECT 1 FROM users u
    WHERE u.user_id = NEW.user_id AND u.company_id = NEW.company_id
      AND u.is_active = 1 AND u.is_deleted = 0
)
BEGIN
    SELECT RAISE(ABORT, 'auth_session_company_mismatch_or_inactive_user');
END;
